contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address depositor, uint amount) public payable {
        require(address(this).balance >= amount);
        // make the Deposit call from this contract on behalf of this contract's address
        c.Deposit{value: amount}();
        // observe c.balances for this contract address
        uint bal = c.balances(address(this));
        // general rule: balance after Deposit must be >= the amount just deposited
        assert(bal >= amount);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: depositor is msg.sender of this call; amount is Ether to send
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read previous balance via public getter
        uint prev = c.balances(address(this));
        // perform deposit sending Ether
        c.Deposit{value: amount}();
        // read new balance
        uint after = c.balances(address(this));
        // general rule: new balance equals previous balance plus the deposited amount
        assert(after == prev + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // record previous balance via public getter
        uint before = c.balances(address(this));
        // perform the deposit (sends Ether to c)
        c.Deposit{value: depositAmount}();
        uint afterBalance = c.balances(address(this));
        // General invariant: Deposit should not reduce the recorded balance
        assert(afterBalance >= before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: depositor address (as payable via sending from this contract is not possible), and amount to send
    // We will simulate deposits from this contract by calling c.Deposit() and c.receive via direct call with value.
    // To allow sending ETH, the test contract must hold sufficient balance; external test harness should fund it.

    function runTest(uint initialFund, uint sendAmt) public {
        // require this contract has enough ETH to send
        require(address(this).balance >= initialFund && initialFund >= sendAmt);

        // Step 1: ensure MinSum and Log are settable before initialization if needed (not required here)
        // Not calling SetMinSum or SetLogFile or Initialized — unnecessary for this property

        // Step 2: record prior balance of this contract in c.balances
        uint before = c.balances(address(this));

        // Step 3: perform a deposit of sendAmt wei to c from this contract
        // Use the receive fallback by calling Deposit with value
        c.Deposit{value: sendAmt}();

        // Step 4: read after balance
        uint after = c.balances(address(this));

        // Assert: if sendAmt == 0 then after == before (original contract allows zero-value deposits and does not change balance when msg.value==0)
        // This is the distinguishing property: mutant rejects zero deposits; original leaves balances unchanged for zero
        assert(!(sendAmt == 0) || after == before);
    }

    // allow receiving ETH so this contract can fund deposits
    receive() external payable {}
}
